			ld (de), a
p_area_si2_e:
			ld (p_area_rs), sp
			ld sp, p_area
			jp ntc_xn
p_area_r:		; end of area
			ld sp, (p_area_rs)
			jp ntc_xn
p_u_c:		; call u (normal)
			pop hl			; x
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_u_x), de
			ld hl, 0
			ld (var_u_u), hl
			ld (var_u_u+2), hl
			ld (p_u_rs), sp
			ld sp, p_u
			jp ntc_xn
p_u_r:		; end of u
			ld sp, (p_u_rs)
			jp ntc_xn
p_showptr_c:		; call showptr (normal)
			pop hl			; what
			ld de, var_showptr_what
			ld b, 40
p_showptr_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_showptr_si0_e
			inc hl
			inc de
			djnz p_showptr_si0
			xor a
			ld (de), a
p_showptr_si0_e:
			pop hl			; p
			ld de, var_showptr_p
			ld bc, 4
			ldir
			ld (p_showptr_rs), sp
			ld sp, p_showptr
			jp ntc_xn
p_showptr_r:		; end of showptr
			ld sp, (p_showptr_rs)
			jp ntc_xn

